CREATE Proc [dbo].[ReportInvoiceSummaryVendorWise] @From as datetime, @To as Datetime, @VendorID as text as Declare @ReportName as nvarchar(max); set @ReportName='Report Invoice Summary';  select CONVERT(VARCHAR(11),@From,106) as [From], CONVERT(VARCHAR(11),@To,106) as [To],invm.InvoiceNo,Vendor,invm.Date,invm.Totalamount,@ReportName as s1,invm.Amount as d1,invm.TotalTax as d2 from InvoiceMaster_CompanyNew invm inner join vendor v on invm.vid=v.vid inner join Split(@VendorID,',') sp on sp.items = v.VID WHERE invm.DATE BETWEEN @From AND @To order by invm.InvoiceNo